Q: Finding all of the outcomes for a Tic-Tac-Toe game A: <p>I've written the whole thing in C++23. Here's the code:</p>
<pre><code>#include &lt;iostream&gt;
#include &lt;array&gt;
#include &lt;algorithm&gt;

using namespace std;

int main()
{
    constexpr int8_t Free = -3, White = 0, Black = 1;
    array&lt;array&lt;int8_t, 3&gt;, 3&gt; board;
    board.fill( { Free, Free, Free } );
    unsigned ties = 0, wins = 0, steps = 0, minSteps = -1;
    double avgSteps = 0.0;
    auto recurse = [&amp;]( this auto &amp;self, int8_t colour ) noexcept -&gt; void
    {
        bool full = true;
        for( size_t row = 3; row--; )
            for( size_t col = 3; col--; )
                if( int8_t &amp;coin = board[row][col]; coin == Free )
                {
                    ++steps;
                    full = false;
                    coin = colour;
                    int needed = colour ? 3 : 0;
                    bool won = board[row][0] + board[row][1] + board[row][2] == needed
                            || board[0][col] + board[1][col] + board[2][col] == needed;
                    if( int mid = board[1][1]; !won &amp;&amp; (row == col || row + col == 2) )
                        won = (board[0][0] + mid + board[2][2]) == needed
                            || (board[0][2] + mid + board[2][0]) == needed;
                    if( !won )
                        self( colour == White ? Black : White );
                    else
                    {
                        ++wins;
                        minSteps = min( steps, minSteps );
                        avgSteps += steps;
                    }
                    coin = Free;
                    --steps;
                }
        ties += full;
    };
    recurse( White );
    avgSteps /= wins;
    cout &lt;&lt; &quot;wins: &quot; &lt;&lt; wins &lt;&lt; endl;
    cout &lt;&lt; &quot;ties: &quot; &lt;&lt; ties &lt;&lt; endl;
    cout &lt;&lt; &quot;all: &quot; &lt;&lt; wins + ties &lt;&lt; endl;
    cout &lt;&lt; &quot;min steps: &quot; &lt;&lt; minSteps &lt;&lt; endl;
    cout &lt;&lt; &quot;avg steps: &quot; &lt;&lt; avgSteps &lt;&lt; endl;
}
</code></pre>
<p>The number of wins is 209,088, the number of ties is 46,080 and together that's 255,168.<br />
The number of minimum steps is five and the number of average steps is about 8.1,</p>

Q: Tic Tac Toe: How to prove that there are 26,830 games possibilities A: <p>I've written the whole thing in C++23. Here's the code:</p>
<pre><code>#include &lt;iostream&gt;
#include &lt;array&gt;

using namespace std;

int main()
{
    constexpr int8_t Free = -3, White = 0, Black = 1;
    array&lt;array&lt;int8_t, 3&gt;, 3&gt; board;
    board.fill( { Free, Free, Free } );
    unsigned ties = 0, wins = 0;
    auto recurse = [&amp;]( this auto &amp;self, int8_t colour ) noexcept -&gt; void
    {
        bool full = true;
        for( size_t row = 3; row--; )
            for( size_t col = 3; col--; )
                if( int8_t &amp;coin = board[row][col]; coin == Free )
                {
                    full = false;
                    coin = colour;
                    int needed = colour ? 3 : 0;
                    bool won = board[row][0] + board[row][1] + board[row][2] == needed
                            || board[0][col] + board[1][col] + board[2][col] == needed;
                    if( int mid = board[1][1]; !won &amp;&amp; (row == col || row + col == 2) )
                        won = (board[0][0] + mid + board[2][2]) == needed
                            || (board[0][2] + mid + board[2][0]) == needed;
                    if( !won )
                        self( colour == White ? Black : White );
                    else
                        ++wins;
                    coin = Free;
                }
        ties += full;
    };
    recurse( White );
    cout &lt;&lt; &quot;wins: &quot; &lt;&lt; wins &lt;&lt; endl;
    cout &lt;&lt; &quot;ties: &quot; &lt;&lt; ties &lt;&lt; endl;
    cout &lt;&lt; &quot;all:  &quot; &lt;&lt; wins + ties &lt;&lt; endl;
}
</code></pre>
<p>The number of wins is 209,088, the number of ties is 46,080 and together that's 255,168.</p>
